  ui_story_5075_50750100_8_dialog_content = "อัก!",
  ui_story_5075_50750100_9_dialog_content = "ระวัง PlayerName!",
  ui_story_5075_50750100_10_dialog_content = "ฉันรู้ว่าคุณสนใจในทิวทัศน์ของราชอาณาจักร Ji แต่เรือแพนี้ไม่ใช่ Shadowind",
