  ui_story_5075_50750202_89_dialog_content = "รู้สึกเหมือนดอกไม้บนต้นพลัมนี้บานขึ้นมาในพริบตา",
  ui_story_5075_50750202_90_dialog_content = "แต่คุณชอบเฉพาะดอกเบโกเนียเท่านั้นใช่ไหม?",
  ui_story_5075_50750202_91_dialog_content = "ใช่ แต่ฉันก็รู้สึกว่าดอกพลัมที่บานวันนี้ก็น่าชื่นชมเช่นกันนะ",
  ui_story_5075_50750301_1_dialog_content = "(แม้ว่าฉันจะมั่นใจเต็มที่เมื่อตกลงที่จะทำการสืบสวนนี้...)",
  ui_story_5075_50750301_2_dialog_content = "(ฉันไม่ได้คาดหวังว่าจะเจออุปสรรคใหญ่ขนาดนี้ทันทีเลย!)",
  ui_story_5075_50750301_3_dialog_content = "เฮ้... การคุ้มครองมากขนาดนี้มันเกินไปนิดนะคุณไม่คิดว่าเป็นไปได้ไหม? ฉันแค่อยากมาช้อปปิ้งเล็กน้อยเท่านั้นเอง.",
  ui_story_5075_50750301_4_dialog_content = "ความเป็นเลิศคุณ ด้วยฐานะที่สูงส่งของคุณ หกทหารยามเพียงเพียงเป็นมาตรการรักษาความปลอดภัยพื้นฐาน ไม่มีอะไรพิเศษเลยครับ",
  ui_story_5075_50750301_5_dialog_content = "ฉันได้สมัครเพิ่มทหารยามเพิ่มอีกเก้าคนเพื่อรับรองความปลอดภัยของคุณแล้ว",
  ui_story_5075_50750301_6_dialog_content = "ยามเพิ่มเติม?",
  ui_story_5075_50750301_7_dialog_content = "ช่างเถอะ, ฉันมีเรื่องสำคัญกว่านี้ที่จะถาม...",
