  ui_story_5075_50750301_9_dialog_content = "เพื่อหลีกเลี่ยงการรบกวนในช่วงเวลาว่างของคุณ เราได้ทำความสะอาดพื้นที่ล่วงหน้าแล้ว",
  ui_story_5075_50750301_10_dialog_content = "แต่นั่นก็ทำให้ประสบการณ์ทั้งหมดพังทลาย!",
