  ui_story_5075_50750601_20_dialog_content = "เธอซื้อเกี๊ยวเพียงหนึ่งลูกและจ่ายด้วยสิ่งนี้",
  ui_story_5075_50750601_21_dialog_content = "นี่คือทองหรือ? ฉันกำลังจะพูดว่ามันมากเกินไป แล้วเธอก็หายไปอย่างกะทันหันเมื่อฉันมองขึ้น.",
