  ui_story_5075_50750601_69_dialog_content = "แต่เราไม่สามารถทิ้งเวทีว่างเปล่าไว้ในระหว่างงานเทศกาลได้ ดังนั้นเราจึงคิดขึ้นมาว่าจะมีการจัดเรียงใหม่",
  ui_story_5075_50750601_70_dialog_content = "ต่อไปนี้ ผู้แสดงเมดมังกรจำนวนหนึ่งจะผลัดกันขึ้นเวที แต่ละคนจะนำเสนอเวอร์ชันของเธอเองของเมดมังกรบนทะเลที่หายนะ",
