  ui_story_5075_50750601_84_dialog_content = "\"คลื่นของมหาสมุทรกว้างใหญ่มืดมัว ดูเหมือนถูกปกคลุมด้วยควัน\"",
  ui_story_5075_50750601_85_dialog_content = "(โอเค, โชว์ให้เห็นว่าคุณกว้างใหญ่และลึกลับแค่ไหนนะ ทะเล)",
  ui_story_5075_50750601_86_dialog_content = "(การขยิบตาให้ฉันไม่ได้เปลี่ยนอะไรเลย! ท-ทั้งนั้น คงต้องทำอะไรสักอย่างให้เกิดความฮือฮาล่ะ)",
