  ui_story_5075_50750601_88_dialog_content = "...",
  ui_story_5075_50750601_89_dialog_content = "(ไม่นะ... อย่าบอกฉันว่าคุณลืมบทพูดของคุณ!)",
  ui_story_5075_50750601_90_dialog_content = "\"พรจากพระเจ้ามากมายสำหรับทุกคน\"! นั่นคือส่วนถัดไป!",
  ui_story_5075_50750601_91_dialog_content = "(ไม่ดีแล้ว—เธอพลาดไปแล้ว เราไม่ควรคาดหวังว่าเฉินนี่จะจำบทได้...)",
  ui_story_5075_50750601_92_dialog_content = "\"เมื่อมังกรชั่วร้ายมาถึง ทั้งดวงอาทิตย์และดวงจันทร์ต่างสูญเสียแสงสว่างของตน\"",
  ui_story_5075_50750601_93_dialog_content = "(หลัว ซง?)",
  ui_story_5075_50750601_94_dialog_content = "\"สายฟ้าคำรามและฟ้าแลบวับวาบ\"",
  ui_story_5075_50750601_95_dialog_content = "(การเคลื่อนไหวของเขาดูแข็งแ stiff และบรรทัดที่เขาพูดก็ไม่ถูกต้องเลย แต่เขากำลังทำอยู่! ทำได้ดีเลย!)",
  ui_story_5075_50750601_96_dialog_content = "(เดี๋ยวนะ, ทำไมเขาถึงไม่เคลื่อนไหวเลย?)",
  ui_story_5075_50750601_97_dialog_content = "(รีบขึ้น! สายฟ้าและฟ้าผ่า!)",
  ui_story_5075_50750601_98_dialog_content = "(งานของฉันเหมือนกันเหรอ?)",
  ui_story_5075_50750601_99_dialog_content = "(ไม่ว่าจะยังไง ถึงเวลาทำฟ้าร้องแล้ว)",
  ui_story_5075_50750601_100_dialog_content = "ครืนนนน!",
  ui_story_5075_50750601_101_dialog_content = "\"ประชาชนมองดูอย่างไม่ไร้กำลังใจในขณะที่วิญญาณชั่วร้ายกำลังกู่ร้องและวิ่งเต้นอย่างเถื่อน!\"",
  ui_story_5075_50750601_102_dialog_content = "\"แต่ไม่นานหลังจากนั้น หญิงสาวมังกรปรากฏตัวและช่วยพวกเขาหลุดพ้นจากความทำลาย\"",
  ui_story_5075_50750601_103_dialog_content = "\"ด้วยพลังที่ไม่มีขีดจำกัดและความมุ่งมั่นที่ไม่สั่นสะเทือน,\"",
  ui_story_5075_50750601_104_dialog_content = "\"เธอชกปีศาจแล้วส่งพวกมันปลิวไปทุกทิศทาง!\"",
  ui_story_5075_50750601_105_dialog_content = "(ดังนั้นตอนนี้เมดมังกรกำลังใช้กำปั้นของเธอเพื่อสู้รึเปล่า?)",
  ui_story_5075_50750601_106_dialog_content = "(แล้วก็ คุณน่าจะเป็นมังกรที่ชั่วร้าย! บทพูดของคุณก็ไม่อาจยุ่งยากไปกว่านี้!)",
  ui_story_5075_50750601_107_dialog_content = "โฮกก!",
  ui_story_5075_50750601_108_dialog_content = "(ในทุกๆความยุ่งเหยิงในละครรถไฟที่เป็นภัยพิบัตินี้ ทำไมคุณถึงต้องทำให้อิคลิพไซท์ดูเหมือนจริงขนาดนั้นเล่า?)",
  ui_story_5075_50750601_109_dialog_content = "(เดี๋ยวนะ!)",
  ui_story_5075_50750601_110_dialog_content = "นี่คือ Eclipsite จริงๆ!",
  ui_story_5075_50750602_1_dialog_content = "ขอบคุณทุกคนที่นำสิ่งดีๆมาให้...",
  ui_story_5075_50750602_2_dialog_content = "เอกลักษณ์... การแสดงออกทางสร้างสรรค์ของ... มังกรหญิงสาวบนทะเลที่วุ่นวาย.",
  ui_story_5075_50750602_3_dialog_content = "หัวหน้าวงดูพ่ายแพ้มาก คงเป็นเพราะเราทำงานได้แย่จริง ๆ",
  ui_story_5075_50750602_4_dialog_content = "ฉันคิดว่าการโจมตีของวิญญาณชั่วร้ายนั้นทำให้เกิดความเสียหายมากที่สุด ถ้าจะพูดตรง ๆ",
  ui_story_5075_50750602_5_dialog_content = "ฉันคิดว่าอิคลิพไซท์ของหลงโจวนานๆจะปรากฏตัวในเมืองเท่าไหร่เนี่ย?",
  ui_story_5075_50750602_6_dialog_content = "เจ้าปีศาจเล็กๆที่เข้าใจไม่ได้, หมอกสีดำที่ไม่สามารถอธิบายได้, และตอนนี้ยังมี Eclipsites ด้วย.",
