  ui_story_5075_50751302_40_dialog_content = "จี๊ด!",
  ui_story_5075_50751302_41_dialog_content = "<color=#e8d9bb>ตัวน้อยใจร้ายลอยอยู่กลางอากาศ สร้างสิ่งกีดขวางที่มองไม่เห็นขึ้นมาด้านบน</color>",
