  ui_story_5075_50751302_43_dialog_content = "<color=#e8d9bb>ภายใต้ความกดดัน, ปีศาจน้อยสั่นคลอน, แต่มันยังคงยกขาเล็ก ๆ ขึ้น, ยกบาริเออร์ป้องกันขึ้น</color>",
  ui_story_5075_50751302_44_dialog_content = "<color=#e8d9bb>แล้วก็มีอีกหนึ่งสิ่งกีดขวางปรากฏขึ้นไม่ไกลจากนั้น</color>",
  ui_story_5075_50751302_45_dialog_content = "โฮกก!",
  ui_story_5075_50751302_46_dialog_content = "<color=#e8d9bb>แล้วก็มีอีกหนึ่ง</color>",
